    rows=m['files'];expected=tree_files(root);expected.pop(path_key(safe(ref['path'])))
    need({path_key(safe(x['path'])) for x in rows}==set(expected),'OUTPUT_MANIFEST_MEMBERSHIP')
    for x in rows:safe(x['path'],safe(root))

